from typing import Protocol

class Greeter(Protocol):
    def greet(self) -> str: ...

class User:
    def greet(self) -> str:
        return "Hi"

def welcome(g: Greeter) -> None:
    print(g.greet())

welcome(User())

def first[T](items: list[T]) -> T:
    return items[0]

